"""Coverage-guided fuzz driver for the Arrow date/time library."""
import atheris
import sys

with atheris.instrument_imports():
    import arrow
    from arrow.parser import DateTimeParser, TzinfoParser, ParserError


def TestOneInput(data):
    fdp = atheris.FuzzedDataProvider(data)

    # Choose which function to fuzz
    choice = fdp.ConsumeIntInRange(0, 5)

    if choice == 0:
        # Fuzz arrow.get() with a string
        s = fdp.ConsumeUnicodeNoSurrogates(fdp.ConsumeIntInRange(0, 256))
        try:
            arrow.get(s)
        except (ParserError, ValueError, TypeError, OverflowError,
                AttributeError, re.error, OSError):
            pass

    elif choice == 1:
        # Fuzz DateTimeParser.parse_iso()
        s = fdp.ConsumeUnicodeNoSurrogates(fdp.ConsumeIntInRange(0, 256))
        parser = DateTimeParser()
        try:
            parser.parse_iso(s, normalize_whitespace=fdp.ConsumeBool())
        except (ParserError, ValueError, TypeError, OverflowError,
                AttributeError, re.error):
            pass

    elif choice == 2:
        # Fuzz DateTimeParser.parse() with a format string
        s = fdp.ConsumeUnicodeNoSurrogates(fdp.ConsumeIntInRange(0, 128))
        fmt = fdp.ConsumeUnicodeNoSurrogates(fdp.ConsumeIntInRange(0, 64))
        parser = DateTimeParser()
        try:
            parser.parse(s, fmt, normalize_whitespace=fdp.ConsumeBool())
        except (ParserError, ValueError, TypeError, OverflowError,
                AttributeError, re.error):
            pass

    elif choice == 3:
        # Fuzz TzinfoParser.parse()
        s = fdp.ConsumeUnicodeNoSurrogates(fdp.ConsumeIntInRange(0, 128))
        try:
            TzinfoParser.parse(s)
        except (ParserError, ValueError, TypeError, OverflowError,
                AttributeError, KeyError):
            pass

    elif choice == 4:
        # Fuzz Arrow.format() with a fuzzed format string
        fmt = fdp.ConsumeUnicodeNoSurrogates(fdp.ConsumeIntInRange(0, 128))
        try:
            a = arrow.utcnow()
            a.format(fmt)
        except (ParserError, ValueError, TypeError, OverflowError,
                AttributeError, KeyError, re.error):
            pass

    elif choice == 5:
        # Fuzz Arrow.dehumanize()
        s = fdp.ConsumeUnicodeNoSurrogates(fdp.ConsumeIntInRange(0, 128))
        try:
            a = arrow.utcnow()
            a.dehumanize(s)
        except (ParserError, ValueError, TypeError, OverflowError,
                AttributeError, KeyError, re.error):
            pass


import re

def main():
    atheris.Setup(sys.argv, TestOneInput)
    atheris.Fuzz()

if __name__ == "__main__":
    main()

"""Coverage-guided fuzz driver for MiniSGL pure-Python components.

Focuses on components that don't require GPU/CUDA:
- SamplingParams validation
- Text processing utilities (find_printable_text, _is_chinese_char)
- Message serialization/deserialization
"""
import atheris
import sys

with atheris.instrument_imports():
    from minisgl.core import SamplingParams
    from minisgl.tokenizer.detokenize import find_printable_text, _is_chinese_char
    from minisgl.message.utils import _serialize_any, deserialize_type, serialize_type


def TestOneInput(data):
    fdp = atheris.FuzzedDataProvider(data)

    choice = fdp.ConsumeIntInRange(0, 4)

    if choice == 0:
        # Fuzz SamplingParams creation and is_greedy property
        temperature = fdp.ConsumeFloatInRange(-100.0, 100.0)
        top_k = fdp.ConsumeIntInRange(-1, 10000)
        top_p = fdp.ConsumeFloatInRange(-1.0, 2.0)
        max_tokens = fdp.ConsumeIntInRange(0, 100000)
        try:
            params = SamplingParams(
                temperature=temperature,
                top_k=top_k,
                top_p=top_p,
                ignore_eos=fdp.ConsumeBool(),
                max_tokens=max_tokens,
            )
            _ = params.is_greedy
        except (ValueError, TypeError, OverflowError):
            pass

    elif choice == 1:
        # Fuzz find_printable_text
        text = fdp.ConsumeUnicodeNoSurrogates(fdp.ConsumeIntInRange(0, 512))
        try:
            find_printable_text(text)
        except (ValueError, TypeError, IndexError):
            pass

    elif choice == 2:
        # Fuzz _is_chinese_char with arbitrary codepoints
        cp = fdp.ConsumeIntInRange(0, 0x10FFFF)
        try:
            _is_chinese_char(cp)
        except (ValueError, TypeError, OverflowError):
            pass

    elif choice == 3:
        # Fuzz _serialize_any with random nested structures
        depth = fdp.ConsumeIntInRange(0, 5)
        obj = _build_random_obj(fdp, depth)
        try:
            _serialize_any(obj)
        except (ValueError, TypeError, OverflowError, AttributeError,
                KeyError, RecursionError, AssertionError):
            pass

    elif choice == 4:
        # Fuzz deserialize_type with random dict data
        type_name = fdp.ConsumeUnicodeNoSurrogates(fdp.ConsumeIntInRange(0, 32))
        num_fields = fdp.ConsumeIntInRange(0, 5)
        data = {"__type__": type_name}
        for _ in range(num_fields):
            key = fdp.ConsumeUnicodeNoSurrogates(fdp.ConsumeIntInRange(1, 16))
            val = fdp.ConsumeUnicodeNoSurrogates(fdp.ConsumeIntInRange(0, 32))
            data[key] = val
        try:
            deserialize_type({}, data)
        except (ValueError, TypeError, KeyError, AttributeError,
                OverflowError, AssertionError):
            pass


def _build_random_obj(fdp, depth):
    """Build a random nested Python object for serialization testing."""
    if depth <= 0 or fdp.remaining_bytes() < 4:
        t = fdp.ConsumeIntInRange(0, 4)
        if t == 0:
            return fdp.ConsumeIntInRange(-1000, 1000)
        elif t == 1:
            return fdp.ConsumeFloat()
        elif t == 2:
            return fdp.ConsumeUnicodeNoSurrogates(fdp.ConsumeIntInRange(0, 32))
        elif t == 3:
            return None
        else:
            return fdp.ConsumeBool()

    container_type = fdp.ConsumeIntInRange(0, 1)
    size = fdp.ConsumeIntInRange(0, 3)
    if container_type == 0:
        return [_build_random_obj(fdp, depth - 1) for _ in range(size)]
    else:
        return {
            fdp.ConsumeUnicodeNoSurrogates(fdp.ConsumeIntInRange(1, 8)):
                _build_random_obj(fdp, depth - 1)
            for _ in range(size)
        }


def main():
    atheris.Setup(sys.argv, TestOneInput)
    atheris.Fuzz()

if __name__ == "__main__":
    main()

"""Coverage-guided fuzz driver for UltraJSON (ujson)."""
import atheris
import sys
from io import StringIO, BytesIO

with atheris.instrument_imports():
    import ujson


def TestOneInput(data):
    fdp = atheris.FuzzedDataProvider(data)

    choice = fdp.ConsumeIntInRange(0, 3)

    if choice == 0:
        # Fuzz ujson.loads() with raw string input
        s = fdp.ConsumeUnicodeNoSurrogates(fdp.ConsumeIntInRange(0, 1024))
        try:
            ujson.loads(s)
        except (ujson.JSONDecodeError, ValueError, TypeError,
                OverflowError, RecursionError):
            pass

    elif choice == 1:
        # Fuzz ujson.loads() with raw bytes input
        b = fdp.ConsumeBytes(fdp.ConsumeIntInRange(0, 1024))
        try:
            ujson.loads(b)
        except (ujson.JSONDecodeError, ValueError, TypeError,
                OverflowError, RecursionError, UnicodeDecodeError):
            pass

    elif choice == 2:
        # Fuzz ujson.dumps() with random generated objects
        obj = _build_random_json(fdp, depth=4)
        ensure_ascii = fdp.ConsumeBool()
        encode_html_chars = fdp.ConsumeBool()
        escape_forward_slashes = fdp.ConsumeBool()
        sort_keys = fdp.ConsumeBool()
        indent = fdp.ConsumeIntInRange(0, 8)
        try:
            encoded = ujson.dumps(
                obj,
                ensure_ascii=ensure_ascii,
                encode_html_chars=encode_html_chars,
                escape_forward_slashes=escape_forward_slashes,
                sort_keys=sort_keys,
                indent=indent,
            )
            # Roundtrip test: verify decode(encode(obj)) works
            ujson.loads(encoded)
        except (ujson.JSONDecodeError, ValueError, TypeError,
                OverflowError, RecursionError):
            pass

    elif choice == 3:
        # Fuzz ujson.load() with BytesIO
        b = fdp.ConsumeBytes(fdp.ConsumeIntInRange(0, 512))
        try:
            ujson.load(BytesIO(b))
        except (ujson.JSONDecodeError, ValueError, TypeError,
                OverflowError, RecursionError, UnicodeDecodeError,
                AttributeError):
            pass


def _build_random_json(fdp, depth):
    """Build a random JSON-serializable Python object."""
    if depth <= 0 or fdp.remaining_bytes() < 4:
        t = fdp.ConsumeIntInRange(0, 5)
        if t == 0:
            return fdp.ConsumeIntInRange(-2**31, 2**31 - 1)
        elif t == 1:
            return fdp.ConsumeRegularFloat()
        elif t == 2:
            return fdp.ConsumeUnicodeNoSurrogates(fdp.ConsumeIntInRange(0, 64))
        elif t == 3:
            return None
        elif t == 4:
            return fdp.ConsumeBool()
        else:
            return fdp.ConsumeUnicodeNoSurrogates(fdp.ConsumeIntInRange(0, 16))

    container_type = fdp.ConsumeIntInRange(0, 1)
    size = fdp.ConsumeIntInRange(0, 5)
    if container_type == 0:
        return [_build_random_json(fdp, depth - 1) for _ in range(size)]
    else:
        return {
            fdp.ConsumeUnicodeNoSurrogates(fdp.ConsumeIntInRange(1, 16)):
                _build_random_json(fdp, depth - 1)
            for _ in range(size)
        }


def main():
    atheris.Setup(sys.argv, TestOneInput)
    atheris.Fuzz()

if __name__ == "__main__":
    main()

